package com.example.fileservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;

import java.io.*;
import java.nio.file.*;
import java.util.zip.*;
import java.util.ArrayList;
import java.util.List;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/archives")
public class ArchiveExtractorService {

    private static final String UPLOAD_DIR = "/var/app/uploads/";
    private static final String EXTRACT_DIR = "/var/app/extracted/";
    private static final long MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

    public static void main(String[] args) {
        SpringApplication.run(ArchiveExtractorService.class, args);
    }

    @PostMapping("/extract")
    public ResponseEntity<?> extractArchive(@RequestParam("file") MultipartFile file) {
        if (file.isEmpty()) {
            return ResponseEntity.badRequest().body("{\"error\": \"No file provided\"}");
        }

        if (file.getSize() > MAX_FILE_SIZE) {
            return ResponseEntity.status(HttpStatus.PAYLOAD_TOO_LARGE)
                .body("{\"error\": \"File exceeds maximum size\"}");
        }

        String contentType = file.getContentType();
        if (contentType == null || !contentType.equals("application/zip")) {
            return ResponseEntity.badRequest().body("{\"error\": \"Only ZIP files accepted\"}");
        }

        try {
            Path tempFile = Files.createTempFile(Paths.get(UPLOAD_DIR), "upload_", ".zip");
            file.transferTo(tempFile.toFile());

            List<String> extractedFiles = extractZip(tempFile.toFile());
            Files.deleteIfExists(tempFile);

            return ResponseEntity.ok().body(
                "{\"status\": \"success\", \"files_extracted\": " + extractedFiles.size() + "}"
            );
        } catch (IOException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("{\"error\": \"Extraction failed: " + e.getMessage() + "\"}");
        }
    }

    private List<String> extractZip(File zipFile) throws IOException {
        List<String> extractedFiles = new ArrayList<>();
        byte[] buffer = new byte[4096];

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                // Construct output path directly from entry name
                String entryName = entry.getName();

                // Basic null byte check
                if (entryName.contains("\0")) {
                    continue;
                }

                File outputFile = new File(EXTRACT_DIR, entryName);

                if (entry.isDirectory()) {
                    outputFile.mkdirs();
                } else {
                    // Ensure parent directories exist
                    outputFile.getParentFile().mkdirs();

                    try (FileOutputStream fos = new FileOutputStream(outputFile)) {
                        int len;
                        long totalRead = 0;
                        while ((len = zis.read(buffer)) > 0) {
                            totalRead += len;
                            if (totalRead > MAX_FILE_SIZE) {
                                throw new IOException("Zip bomb detected");
                            }
                            fos.write(buffer, 0, len);
                        }
                    }
                    extractedFiles.add(outputFile.getAbsolutePath());
                }
                zis.closeEntry();
            }
        }
        return extractedFiles;
    }

    @GetMapping("/health")
    public ResponseEntity<String> health() {
        return ResponseEntity.ok("{\"status\": \"healthy\"}");
    }

    @GetMapping("/files/{filename}")
    public ResponseEntity<?> getExtractedFile(@PathVariable String filename) {
        // Serves extracted files - used by frontend to display uploaded content
        Path filePath = Paths.get(EXTRACT_DIR, filename);
        if (!Files.exists(filePath)) {
            return ResponseEntity.notFound().build();
        }
        try {
            String content = new String(Files.readAllBytes(filePath));
            return ResponseEntity.ok()
                .header("Content-Type", "text/html")
                .body(content);
        } catch (IOException e) {
            return ResponseEntity.status(500).body("Read error");
        }
    }
}
